import sqlite3
import hashlib
import os
import re
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
import json
import hmac
import time

DB_PATH = ':memory:'
SECRET_KEY = os.urandom(32)

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.execute("CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT UNIQUE, password_hash TEXT, role TEXT DEFAULT 'user')")
    conn.execute("CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id INTEGER, expires_at INTEGER)")
    conn.execute("CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY, action TEXT, details TEXT, timestamp INTEGER)")
    conn.commit()
    return conn

def hash_password(password, salt=None):
    if salt is None:
        salt = os.urandom(16)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + dk.hex()

def verify_password(password, stored_hash):
    salt_hex, hash_hex = stored_hash.split(':')
    salt = bytes.fromhex(salt_hex)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(dk.hex(), hash_hex)

class QueryBuilder:
    """Safe query builder with parameterized queries."""

    def __init__(self, table):
        self.table = table
        self._conditions = []
        self._params = []
        self._order = None
        self._limit = None

    def where(self, column, operator, value):
        allowed_operators = ['=', '!=', '<', '>', '<=', '>=', 'LIKE']
        if operator not in allowed_operators:
            raise ValueError(f"Invalid operator: {operator}")
        # Validate column name - alphanumeric and underscore only
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', column):
            raise ValueError(f"Invalid column name: {column}")
        self._conditions.append(f"{column} {operator} ?")
        self._params.append(value)
        return self

    def order_by(self, column, direction='ASC'):
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', column):
            raise ValueError(f"Invalid column name: {column}")
        if direction.upper() not in ('ASC', 'DESC'):
            raise ValueError(f"Invalid direction: {direction}")
        self._order = f"{column} {direction.upper()}"
        return self

    def limit(self, n):
        self._limit = int(n)
        return self

    def build_select(self, columns='*'):
        if columns != '*':
            cols = columns.split(',')
            for col in cols:
                col = col.strip()
                if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', col):
                    raise ValueError(f"Invalid column: {col}")
        query = f"SELECT {columns} FROM {self.table}"
        if self._conditions:
            query += " WHERE " + " AND ".join(self._conditions)
        if self._order:
            query += f" ORDER BY {self._order}"
        if self._limit:
            query += f" LIMIT {self._limit}"
        return query, self._params


class SearchFilter:
    """Applies user-defined search filters to queries."""

    ALLOWED_FIELDS = {'username': 'username', 'role': 'role', 'id': 'id'}

    def __init__(self, filter_spec):
        self.field = filter_spec.get('field', '')
        self.value = filter_spec.get('value', '')
        self.match_type = filter_spec.get('match_type', 'exact')

    def validate(self):
        if self.field not in self.ALLOWED_FIELDS:
            return False
        if len(self.value) > 100:
            return False
        if self.match_type not in ('exact', 'prefix', 'contains'):
            return False
        return True

    def apply(self, query_builder):
        if not self.validate():
            raise ValueError("Invalid filter")

        db_column = self.ALLOWED_FIELDS[self.field]

        if self.match_type == 'exact':
            query_builder.where(db_column, '=', self.value)
        elif self.match_type == 'prefix':
            query_builder.where(db_column, 'LIKE', self.value + '%')
        elif self.match_type == 'contains':
            query_builder.where(db_column, 'LIKE', '%' + self.value + '%')

        return query_builder


def build_audit_query(user_id, action_filter=None, date_range=None):
    """Build audit log query with optional filters."""
    qb = QueryBuilder('audit_log')

    if user_id is not None:
        qb.where('user_id', '=', user_id)

    if action_filter:
        qb.where('action', '=', action_filter)

    qb.order_by('timestamp', 'DESC')
    qb.limit(50)

    return qb.build_select()


def search_users(conn, filters, requesting_user_role):
    """Search users with applied filters. Only admins can search."""
    if requesting_user_role != 'admin':
        return {'error': 'Unauthorized'}, 403

    qb = QueryBuilder('users')

    for filter_spec in filters:
        sf = SearchFilter(filter_spec)
        sf.apply(qb)

    query, params = qb.build_select('id, username, role')
    cursor = conn.execute(query, params)
    results = [{'id': row[0], 'username': row[1], 'role': row[2]} for row in cursor.fetchall()]
    return {'users': results}, 200


def get_user_profile(conn, user_id, fields=None):
    """Get user profile. Fields parameter controls which columns to return."""
    if fields is None:
        fields = ['id', 'username', 'role']

    # Validate each field
    allowed = {'id', 'username', 'role'}
    validated_fields = [f for f in fields if f in allowed]

    if not validated_fields:
        validated_fields = ['id', 'username', 'role']

    columns = ', '.join(validated_fields)
    query = f"SELECT {columns} FROM users WHERE id = ?"
    cursor = conn.execute(query, (user_id,))
    row = cursor.fetchone()
    if row:
        return dict(zip(validated_fields, row))
    return None


def log_action(conn, action, details, user_id=None):
    """Log an action to the audit table."""
    conn.execute(
        "INSERT INTO audit_log (action, details, timestamp) VALUES (?, ?, ?)",
        (action, details, int(time.time()))
    )
    conn.commit()


def format_log_entry(action, username, detail_msg):
    """Format a log entry string for the audit log."""
    timestamp = int(time.time())
    return f"[{timestamp}] {action} by {username}: {detail_msg}"


def create_session(conn, user_id):
    token = os.urandom(32).hex()
    expires = int(time.time()) + 3600
    conn.execute("INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)",
                 (token, user_id, expires))
    conn.commit()
    return token


def validate_session(conn, token):
    if not token or not re.match(r'^[a-f0-9]{64}$', token):
        return None
    cursor = conn.execute(
        "SELECT user_id, expires_at FROM sessions WHERE token = ?", (token,))
    row = cursor.fetchone()
    if row and row[1] > int(time.time()):
        return row[0]
    return None


def handle_report(conn, report_type, params, user_role):
    """Generate reports based on type and parameters."""
    if user_role != 'admin':
        return {'error': 'Unauthorized'}, 403

    if report_type == 'user_activity':
        target_user = params.get('target_user', '')
        # Use parameterized query for safety
        query = "SELECT action, details, timestamp FROM audit_log WHERE details LIKE ?"
        cursor = conn.execute(query, (f'%{target_user}%',))
        return {'results': [dict(zip(['action', 'details', 'timestamp'], row)) for row in cursor.fetchall()]}, 200

    elif report_type == 'custom':
        # Custom report allows specifying grouping
        group_field = params.get('group_by', 'action')
        # Validate group_by field
        allowed_group_fields = {'action', 'user_id', 'timestamp'}
        if group_field not in allowed_group_fields:
            return {'error': 'Invalid group_by field'}, 400

        time_range = params.get('time_range', '3600')
        try:
            time_range = int(time_range)
        except (ValueError, TypeError):
            time_range = 3600

        since = int(time.time()) - time_range
        query = f"SELECT {group_field}, COUNT(*) FROM audit_log WHERE timestamp > ? GROUP BY {group_field}"
        cursor = conn.execute(query, (since,))
        return {'results': [{'group': row[0], 'count': row[1]} for row in cursor.fetchall()]}, 200

    elif report_type == 'lookup':
        # Lookup specific log entries by composite key
        entry_ids = params.get('ids', '')
        # Parse comma-separated IDs
        id_list = [x.strip() for x in entry_ids.split(',') if x.strip()]
        # Validate each ID is numeric
        validated_ids = []
        for id_val in id_list:
            if re.match(r'^\d+$', id_val):
                validated_ids.append(id_val)

        if not validated_ids:
            return {'results': []}, 200

        # Build IN clause - IDs are validated as numeric
        placeholders = ','.join(validated_ids)
        query = f"SELECT id, action, details, timestamp FROM audit_log WHERE id IN ({placeholders})"
        cursor = conn.execute(query)
        return {'results': [dict(zip(['id', 'action', 'details', 'timestamp'], row)) for row in cursor.fetchall()]}, 200

    elif report_type == 'summary':
        # Summary with user-specified label
        label = params.get('label', 'Report')
        since = int(time.time()) - 86400
        query = "SELECT COUNT(*), MAX(timestamp) FROM audit_log WHERE timestamp > ?"
        cursor = conn.execute(query, (since,))
        row = cursor.fetchone()
        return {'label': label, 'count': row[0], 'latest': row[1]}, 200

    return {'error': 'Unknown report type'}, 400


class APIHandler(BaseHTTPRequestHandler):

    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path
        params = parse_qs(parsed.query)

        conn = get_db()

        if path == '/api/users/search':
            token = self.headers.get('Authorization', '').replace('Bearer ', '')
            user_id = validate_session(conn, token)
            if not user_id:
                self.send_error(401)
                return

            user = get_user_profile(conn, user_id)
            filters_raw = params.get('filters', ['[]'])[0]
            try:
                filters = json.loads(filters_raw)
            except json.JSONDecodeError:
                self.send_error(400)
                return

            result, status = search_users(conn, filters, user.get('role'))
            self.send_response(status)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps(result).encode())

        elif path == '/api/report':
            token = self.headers.get('Authorization', '').replace('Bearer ', '')
            user_id = validate_session(conn, token)
            if not user_id:
                self.send_error(401)
                return

            user = get_user_profile(conn, user_id)
            report_type = params.get('type', [''])[0]
            report_params = {}
            for k, v in params.items():
                if k != 'type':
                    report_params[k] = v[0]

            result, status = handle_report(conn, report_type, report_params, user.get('role'))
            self.send_response(status)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps(result).encode())

        else:
            self.send_error(404)

    def do_POST(self):
        parsed = urlparse(self.path)
        path = parsed.path
        content_length = int(self.headers.get('Content-Length', 0))
        body = self.rfile.read(content_length)

        conn = get_db()

        if path == '/api/register':
            try:
                data = json.loads(body)
            except json.JSONDecodeError:
                self.send_error(400)
                return

            username = data.get('username', '')
            password = data.get('password', '')

            if not username or not password:
                self.send_error(400)
                return

            if not re.match(r'^[a-zA-Z0-9_]{3,30}$', username):
                self.send_error(400)
                return

            if len(password) < 8:
                self.send_error(400)
                return

            pw_hash = hash_password(password)
            try:
                conn.execute("INSERT INTO users (username, password_hash) VALUES (?, ?)",
                           (username, pw_hash))
                conn.commit()
                log_action(conn, 'register', format_log_entry('register', username, 'new account'))
                self.send_response(201)
                self.end_headers()
            except sqlite3.IntegrityError:
                self.send_error(409)

        elif path == '/api/login':
            try:
                data = json.loads(body)
            except json.JSONDecodeError:
                self.send_error(400)
                return

            username = data.get('username', '')
            password = data.get('password', '')

            cursor = conn.execute("SELECT id, password_hash FROM users WHERE username = ?", (username,))
            row = cursor.fetchone()

            if row and verify_password(password, row[1]):
                token = create_session(conn, row[0])
                log_action(conn, 'login', format_log_entry('login', username, 'success'))
                self.send_response(200)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                self.wfile.write(json.dumps({'token': token}).encode())
            else:
                log_action(conn, 'login_failed', format_log_entry('login_failed', username, 'invalid credentials'))
                self.send_error(401)

        else:
            self.send_error(404)


if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), APIHandler)
    server.serve_forever()
